const PixelArt = (() => {
  const cache = new Map(), glyphs = '.0123456789ABCDEFGH';
  function frame(who, tick = 0, tilt = 0, pose = 'idle') {
    const phase = ((Math.floor(tick / 9) % 4) + 4) % 4;
    if (who === 'akari') {
      const amount = Math.abs(tilt), direction = tilt < 0 ? 'left' : 'right';
      return { key: 'akari-' + (amount < .18 ? 'idle' : direction + (amount < .65 ? '1' : '2')), index: phase };
    }
    return { key: who + '-' + (pose === 'cast' ? 'cast' : 'idle'), index: phase };
  }
  function palette(name, tint) {
    const base = PIXEL_DATA.palettes[name];
    if (!tint) return base;
    if (tint === 'hurt') return base.map((c, i) => i === 0 ? '#40304b' : '#c7adb9');
    // COLの色を受け取り、鬼火を弾より暗くする。白い芯は使わない。
    if (tint[0] === '#') {
      const rgb = [1,3,5].map(i => parseInt(tint.slice(i,i+2),16));
      return base.map((_, i) => '#' + rgb.map((c,j) => Math.round(c * (.22 + i * .10) + [13,16,27][j]).toString(16).padStart(2,'0')).join(''));
    }
    if (tint === 'red') {
      const red = {moth:['#270f20','#421629','#632435','#87343f','#a84d4c','#c0705d','#d39a77','#dfb68a','#71432e','#a77448','#d5a364','#a96060','#5b2637','#984554','#bd7366','#d3a080'],
        moon:['#230d19','#56303c','#793541','#9d4a49','#ba6555','#ca8565','#784b50','#462737'],
        back:['#140c19','#1a0d1b','#24101d','#2d1721','#3a2028','#492b32','#58333b','#65443e','#805347','#976851','#aa7f61','#39232c']};
      return red[name] || base;
    }
    return base;
  }
  function canvas(key, index = 0, tint = '') {
    const def = PIXEL_DATA.sprites[key]; if (!def) return null;
    index = ((Math.floor(index) % def.frames.length) + def.frames.length) % def.frames.length;
    const id = key + ':' + index + ':' + tint;
    if (cache.has(id)) return cache.get(id);
    const c = document.createElement('canvas'); c.width = def.w; c.height = def.h;
    const g = c.getContext('2d'), pal = palette(def.palette,tint), rows = def.frames[index];
    for (let y=0;y<def.h;y++) for(let x=0;x<def.w;) {
      const ch = rows[y][x]; let end=x+1; while(end<def.w && rows[y][end]===ch) end++;
      if(ch!=='.'){g.fillStyle=pal[glyphs.indexOf(ch)-1];g.fillRect(x,y,end-x,1);} x=end;
    }
    cache.set(id,c); return c;
  }
  function draw(ctx,key,x,y,index=0,{scale=1,tint='',flip=false,eclipse=false}={}) {
    const c=canvas(key,index,tint); if(!c)return false;
    // 拡大途中の大蛾だけ例外。それ以外は整数倍以外を受け付けない。
    if(!eclipse)scale=Math.max(1,Math.round(scale));
    ctx.save();ctx.imageSmoothingEnabled=false;
    const w=Math.round(c.width*scale),h=Math.round(c.height*scale),left=Math.round(x-w/2),top=Math.round(y-h/2);
    if(flip){ctx.translate(left+w,top);ctx.scale(-1,1);ctx.drawImage(c,0,0,w,h);}
    else ctx.drawImage(c,left,top,w,h);
    ctx.restore();return true;
  }
  return {frame,canvas,draw,data:PIXEL_DATA};
})();
